initJs:
function(container, apiUrl, tables) {
  let selectedProductId = null;
  let currentPredictionData = null;

  // 店舗データを読み込み
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリを読み込み（商品マスタから重複除去）
  async function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const option = document.createElement('option');
        option.value = categoryId;
        option.textContent = `カテゴリ${categoryId.substring(0, 8)}`;
        categorySelect.appendChild(option);
      });
    }
  }

  // 商品リストを表示
  function renderProductList(products, predictions = []) {
    const productList = container.querySelector('#product-list');

    if (!products || products.length === 0) {
      productList.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px;">該当する商品が見つかりません</div>';
      return;
    }

    const html = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID);
      const isSelected = selectedProductId === product.商品ID;

      return `
        <div class="product-item" data-product-id="${product.商品ID}" 
             style="padding: 12px; border: 1px solid var(--border); border-radius: 4px; margin-bottom: 8px; cursor: pointer; 
                    background: ${isSelected ? 'var(--primary)' : 'var(--bg-card)'}; 
                    color: ${isSelected ? '#fff' : 'var(--text)'};">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-weight: 600;">${product.商品名}</div>
              <div style="font-size: 14px; opacity: 0.8;">JANコード: ${product.商品コード}</div>
            </div>
            <div style="text-align: right;">
              ${prediction ? `
                <div style="font-size: 14px;">予測需要: ${prediction.予測数量}個</div>
                <div style="font-size: 14px;">推奨発注: ${prediction.推奨発注数量}個</div>
                <div style="font-size: 12px;">精度: ${prediction.予測精度}%</div>
              ` : '<div style="font-size: 14px; opacity: 0.6;">予測データなし</div>'}
            </div>
          </div>
        </div>
      `;
    }).join('');

    productList.innerHTML = html;

    // 商品選択イベント
    productList.addEventListener('click', (e) => {
      const productItem = e.target.closest('.product-item');
      if (productItem) {
        const productId = productItem.dataset.productId;
        selectProduct(productId, products, predictions);
      }
    });
  }

  // 商品選択処理
  function selectProduct(productId, products, predictions) {
    selectedProductId = productId;
    const product = products.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId);

    // 商品リストの表示を更新
    renderProductList(products, predictions);

    // 商品の基本情報をパラメータに反映
    if (product) {
      container.querySelector('#lead-time').value = product.リードタイム日数 || 7;
    }

    // 予測データがある場合はAI推奨発注量を設定
    if (prediction) {
      container.querySelector('#ai-recommended').value = prediction.推奨発注数量;
      currentPredictionData = prediction;
    } else {
      container.querySelector('#ai-recommended').value = '';
      currentPredictionData = null;
    }

    // 手動調整をクリア
    container.querySelector('#manual-adjustment').value = '';

    // 計算結果をクリア
    container.querySelector('#calculation-result').innerHTML = 
      '<div style="color: var(--text-muted); text-align: center; padding: 20px;">パラメータを設定して計算実行してください</div>';
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const currentStock = container.querySelector('#current-stock').value;
    const safetyStock = container.querySelector('#safety-stock').value;
    const leadTime = container.querySelector('#lead-time').value;
    const seasonalFactor = container.querySelector('#seasonal-factor').value;
    const manualAdjustment = container.querySelector('#manual-adjustment').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!selectedProductId) {
      showError('商品を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    if (currentStock && parseFloat(currentStock) < 0) {
      showError('在庫数は0以上の値を入力してください');
      return false;
    }

    if (safetyStock && isNaN(parseFloat(safetyStock))) {
      showError('安全在庫には数値を入力してください');
      return false;
    }

    if (leadTime && (parseFloat(leadTime) < 1 || parseFloat(leadTime) > 365)) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return false;
    }

    if (seasonalFactor && (parseFloat(seasonalFactor) < 0.01 || parseFloat(seasonalFactor) > 9.99)) {
      showError('季節補正係数は0.01-9.99の範囲で入力してください');
      return false;
    }

    if (manualAdjustment && parseFloat(manualAdjustment) < 0) {
      showError('発注量は0以上の値を入力してください');
      return false;
    }

    return true;
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!validateInputs()) return;

    const currentStock = parseFloat(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseFloat(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseFloat(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseFloat(container.querySelector('#weather-impact').value) / 100;
    const eventImpact = parseFloat(container.querySelector('#event-impact').value) / 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;
    const manualAdjustment = container.querySelector('#manual-adjustment').value;

    let baseOrderQuantity = 0;

    // AI推奨値または手動調整値を基準とする
    if (manualAdjustment) {
      baseOrderQuantity = parseFloat(manualAdjustment);
    } else if (currentPredictionData) {
      baseOrderQuantity = currentPredictionData.推奨発注数量;
    } else {
      // 予測データがない場合の簡易計算
      const estimatedDemand = Math.max(10, Math.floor(Math.random() * 100)); // ダミー需要
      baseOrderQuantity = estimatedDemand;
    }

    // 各種調整を適用
    let adjustedQuantity = baseOrderQuantity;
    adjustedQuantity *= weatherImpact;
    adjustedQuantity *= eventImpact;
    adjustedQuantity *= seasonalFactor;

    // リードタイム期間の需要を考慮
    const leadTimeDemand = adjustedQuantity * (leadTime / 7); // 週単位で計算

    // 最終発注量 = リードタイム期間需要 + 安全在庫 - 現在在庫
    const finalOrderQuantity = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 結果表示
    const resultHtml = `
      <div style="background: var(--bg-main); padding: 16px; border-radius: 4px;">
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px;">
          <div>
            <div style="color: var(--text-muted); font-size: 14px;">基準発注量</div>
            <div style="color: var(--text); font-size: 18px; font-weight: 600;">${baseOrderQuantity}個</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 14px;">調整後発注量</div>
            <div style="color: var(--text); font-size: 18px; font-weight: 600;">${Math.ceil(adjustedQuantity)}個</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 14px;">最終推奨発注量</div>
            <div style="color: var(--primary); font-size: 24px; font-weight: 700;">${finalOrderQuantity}個</div>
          </div>
        </div>
        <div style="margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border);">
          <div style="color: var(--text-muted); font-size: 14px; margin-bottom: 8px;">計算内訳</div>
          <div style="color: var(--text); font-size: 14px; line-height: 1.5;">
            • 天候影響: ${(weatherImpact * 100).toFixed(0)}%<br>
            • イベント影響: ${(eventImpact * 100).toFixed(0)}%<br>
            • 季節補正: ${seasonalFactor}<br>
            • リードタイム: ${leadTime}日<br>
            • 現在在庫: ${currentStock}個<br>
            • 安全在庫: ${safetyStock}個
          </div>
        </div>
      </div>
    `;

    container.querySelector('#calculation-result').innerHTML = resultHtml;
  }

  // 検索処理
  async function searchProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchKeyword = container.querySelector('#product-search').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const products = await window.aivicApi.list(2); // 商品マスタ
    if (!products) return;

    let filteredProducts = products.filter(p => p.有効フラグ);

    // カテゴリフィルタ
    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    // キーワード検索
    if (searchKeyword) {
      const keyword = searchKeyword.toLowerCase();
      filteredProducts = filteredProducts.filter(p => 
        p.商品名.toLowerCase().includes(keyword) || 
        p.商品コード.toLowerCase().includes(keyword)
      );
    }

    renderProductList(filteredProducts);
  }

  // AI予測実行
  async function executeAIPrediction() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return;
    }

    // 需要予測結果を取得
    const predictions = await window.aivicApi.list(8); // 需要予測結果
    if (predictions) {
      const storePredictions = predictions.filter(p => 
        p.店舗ID === storeId &&
        p.予測対象日 >= startDate &&
        p.予測対象日<= endDate
      );

      // 現在表示中の商品リストを更新
      const productList = container.querySelector('#product-list');
      if (productList.children.length > 0) {
        const products = await window.aivicApi.list(2);
        if (products) {
          const filteredProducts = products.filter(p => p.有効フラグ);
          renderProductList(filteredProducts, storePredictions);
        }
      }
    }
  }

  // スライダー値の表示更新
  function updateSliderValues() {
    const weatherSlider = container.querySelector('#weather-impact');
    const eventSlider = container.querySelector('#event-impact');
    const weatherValue = container.querySelector('#weather-value');
    const eventValue = container.querySelector('#event-value');

    weatherSlider.addEventListener('input', () => {
      weatherValue.textContent = weatherSlider.value;
    });

    eventSlider.addEventListener('input', () => {
      eventValue.textContent = eventSlider.value;
    });
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 画面遷移
  container.querySelector('#btn-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1778591780173');
  });

  container.querySelector('#btn-order-management').addEventListener('click', () => {
    window.showScreen('scr-1778591852463');
  });

  // 初期化
  loadStores();
  loadCategories();
  updateSliderValues();

  // デフォルト日付設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#start-date').value = today.toISOString().split('T')[0];
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
}
